import (
	"fmt"
	"os"
	"path/filepath"
)

func readFileFromDir(filename, dirPath string) string {
	filePath := filepath.Join(dirPath, filename)
	content, err := os.ReadFile(filePath)
	if err != nil {
		return ""
	}
	return string(content)
}

